effect.shader:
void main(){
    vec2 uv;
    if(mode==0){
        vec2 p = acScreenNorm - 0.5;
        float r = length(p)*2.0;
        float a = (atan(p.y,p.x)+3.14159)/6.28318;
        uv = vec2(a, r);
    } else {
        float a = acScreenNorm.x*6.28318 - 3.14159;
        float r = acScreenNorm.y*0.5;
        uv = vec2(0.5+cos(a)*r, 0.5+sin(a)*r);
    }
    gl_FragColor = texture2DCv(inputImg.texture, clamp(uv,0.0,1.0));
}
